import numpy as np
from scipy.optimize import least_squares
y=dA_dt; var=np.var(y)
def model(p,t,A):
    # two exp-terms + one power term
    return (p[0]*t**p[1]*A**p[2]*np.exp(-p[3]*A) + p[4]*t**p[5]*A**p[6]*np.exp(-p[7]*A)
            + p[8]*t**p[9]*A**p[10])
best=None
rng=np.random.default_rng(0)
for trial in range(300):
    p0=np.concatenate([rng.normal(0,2,1),rng.uniform(0,2,1),rng.uniform(-1,3,1),rng.uniform(0,3,1),
                       rng.normal(0,2,1),rng.uniform(0,2,1),rng.uniform(-1,3,1),rng.uniform(-1,3,1),
                       rng.normal(0,2,1),rng.uniform(0,2,1),rng.uniform(-1,3,1)])
    try:
        r=least_squares(lambda p: model(p,t,A)-y, p0, method='lm', max_nfev=4000)
    except Exception as e:
        continue
    e=np.mean(r.fun**2)/var
    if best is None or e<best[0]: best=(e,r.x)
print(best[0]); print(np.round(best[1],4))
